head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.nPreRow = -1;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS20100.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function() {
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);
    btn_delete.hide();
    await scwin.ins_Search();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_CntrInfo_OnLoadError
 * @description dts_CntrInfo 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_CntrInfo_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_CntrInfo);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS20100.dts_CntrInfo_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_CntrInfo_OnLoadCompleted
 * @description dts_CntrInfo 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_CntrInfo_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_CntrInfo.errorMsg) {
            await $c.win.alert(dts_CntrInfo.errorMsg);
        } else {
            txb_TotalCnt.setValue("총 " + rowcount + "건");
        }

        // 데이터가 없는 경우
        if (rowcount === 0) {
            fn_CtrlBtn_temp("no_data");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS20100.dts_CntrInfo_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_delete_onclick
 * @description 「삭제」 클릭 이벤트
