};

/**
 * @method
 * @name dts_CntrInfo_OnRowPosChanged
 * @description Cntr Info On Row Pos Changed 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_CntrInfo_OnRowPosChanged = function(row) {
    try {
        dts_CntrInfo.undoRow(scwin.nPreRow);
        scwin.nPreRow = row;

        // 조회된 것들은 국가코드 비활성, 신규로 생성된 것만 활성.
        if (dts_CntrInfo.getCellData(row, "SELECTED") === "Y") {
            edt_CNTR_CD.setReadOnly(true);
            fn_CtrlBtn_temp("update");
        } else {
            edt_CNTR_CD.setReadOnly(false);
            fn_CtrlBtn_temp("insert");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS20100.dts_CntrInfo_OnRowPosChanged" });
    }
};

