///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name ins_Search
 * @description 국가코드조회 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_Search = async function() {
    // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크.
    if (!await scwin.chkValid("select")) {
        return;
    }

    // Lodaing~~~ 표시
    const sbmOptions = {
        id : "sbm_dts_CntrInfo",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_CntrInfo=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name ins_Insert
 * @description 국가코드 입력
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_Insert = async function() {
    // 사전체크
    if (!await scwin.chkValid("insert")) {
        return;
    }
    if (!confirm("저장하시겠습니까?")) {
        return;
    }
    trs_Save.KeyName = "toinb_dataid4";
    // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     EMP_NO : js_emp_no,
    //     EMP_NM : js_emp_nm
    // };
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/EtcInfoAction.do",
        ref : "dts_CntrInfo",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name ins_Update
 * @description 국가코드 수정
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_Update = async function() {
    // 사전체크
    if (!await scwin.chkValid("update")) {
        return;
    }
    if (!confirm("수정하시겠습니까?")) {
        return;
    }
    trs_Save.KeyName = "toinb_dataid4";
    // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     EMP_NO : js_emp_no,
    //     EMP_NM : js_emp_nm
    // };
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/EtcInfoAction.do",
        ref : "dts_CntrInfo",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name duplicateDChk
 * @description 국가코드 중복체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.duplicateDChk = async function() {
    const sbmOptions = {
        id : "sbm_dts_DuplChk",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_DuplChk=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name ins_Delete
 * @description 국가코드 삭제
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_Delete = async function() {
    if (!confirm("삭제하시겠습니까?")) {
        return;
    }
    // dts_Delete.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
    dts_Delete.insertRow();
    dts_Delete.setCellData(1, "CNTR_CD", dts_CntrInfo.getCellData(dts_CntrInfo.getRowPosition(), "CNTR_CD"));
    trs_Delete.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_trs_Delete",
        action : "/EtcInfoAction.do",
        ref : "dts_Delete",
        target : "trs_Delete=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @returns {void}
 * @hidden N
 */
scwin.initDs = function() {
    dts_CntrInfo.removeAll();
};

/**
 * @method
 * @name chkValid
 * @description 사전체크
 * @param {*} pGubun pGubun
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkValid = async function(pGubun) {
    if (pGubun === undefined || pGubun === "select") {
        return true;
    }
    if (edt_CNTR_CD.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "국가코드(숫자 세자리)"));
        edt_CNTR_CD.focus();
        return false;
    }
    if (edt_CNTR_CD.getValue().length !== 3) {
        await $c.win.alert("국가코드를 숫자 3자리로 입력하세요.");
        edt_CNTR_CD.focus();
        return false;
    }
    if (edt_CNTR_CD2.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "국가코드(문자 두자리)"));
        edt_CNTR_CD2.focus();
        return false;
    }
    if (edt_CNTR_CD2.getValue().length !== 2) {
        await $c.win.alert("국가코드를 문자 2자리로 입력하세요.");
        edt_CNTR_CD2.focus();
        return false;
    }
    if (edt_CNTR_CD3.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "국가코드(문자 세자리)"));
        edt_CNTR_CD3.focus();
        return false;
    }
    if (edt_CNTR_CD3.getValue().length !== 3) {
        await $c.win.alert("국가코드를 문자 3자리로 입력하세요.");
        edt_CNTR_CD3.focus();
        return false;
    }
    if (txb_CNTR_NM.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "국가명"));
        txb_CNTR_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_CNTR_NM, 80, "국가명")) {
        // txb_COM_ENG_NM.value = "";
        txb_CNTR_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_CNTR_ENG_NM, 60, "국가영문명")) {
        // txb_COM_ENG_NM.value = "";
        txb_CNTR_ENG_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_CNTR_ENG_SRT_NM, 60, "국가영문약명")) {
        // txb_COM_ENG_NM.value = "";
        txb_CNTR_ENG_SRT_NM.focus();
        return false;
    }
    if (pGubun === "update") {
        if (!$c.cp.isModified(dts_CntrInfo)) {
            await $c.win.alert("변경된 데이터가 없습니다.");
            return false;
        }

        // 수정가능 데이터인지 체크
        if (dts_CntrInfo.getCellData(dts_CntrInfo.getRowPosition(), "SELECTED") !== "Y") {
            await $c.win.alert("수정 대상 데이터가 아닙니다.");
            return false;
        }
    } else if (pGubun === "insert") {
        // 입력가능 데이터인지 체크
        if (dts_CntrInfo.getCellData(dts_CntrInfo.getRowPosition(), "SELECTED") === "Y") {
            await $c.win.alert("신규등록 대상 데이터가 아닙니다.");
            return false;
        }

        // 국가코드 중복 체크.
        await scwin.duplicateDChk();
        if (dts_DuplChk.getCellData(1, "CNT") > 0) {
            await $c.win.alert("이미 등록된 국가코드 입니다.");
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name new
 * @description 신규버튼 클릭
 * @returns {void}
 * @hidden N
 */
scwin.new = function() {
    dts_CntrInfo.insertRow();
    cmb_ACTIV_YN.setSelectedIndex(0);
    edt_CNTR_CD.focus();
};
